INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (11, "だからわたし、\n勇気を出して言ってみたんです！\nお友だちになりませんか、って。", 1, 10, 1, 0, 72021, 1, 72, 0, 0);
