INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (11, "それでも……適性など踏み越えて、\n己の道を突き進むのが冒険者です。\n一度決めたことを、\n曲げるわけには参りません……！", 1, 10, 1, 0, 82021, 1, 82, 0, 0);
INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (91, "", 0, 0, 0, "", 82022, "", 82, "", "");
