INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (11, "……でも。\n今回の冒険で、夢見ることは\n大きな力だと知りましたから。", 1, 10, 1, 0, 142024, 1, 142, 0, 0);
